  "mainEntity": [
    {
      "@type": "Question",
      "name": "هل يمكن تركيب كاميرا الدوم في الخارج؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "ممكن بشرط أن تكون درجة الحماية IP مناسبة للتعرض الخارجي، ووجود ذراع أو غطاء واقٍ. الدوم الداخلي البسيط لا يصلح للخارج ويتدهور سريعًا في مناخ الإسكندرية."
      }
    },
    {
      "@type": "Question",
      "name": "هل كاميرا البوليت أوضح في الرؤية الليلية من كاميرا الدوم؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "غالبًا نعم في المواضع الخارجية، لأن هيكل البوليت يستوعب مصفوفة أكبر من مصابيح الأشعة تحت الحمراء. في الغرف الداخلية، تتساوى النتيجة وتصبح دقة المستشعر هي الفارق."
      }
    },
    {
      "@type": "Question",
      "name": "أيهما أقل لفتًا للانتباه: الدوم أم البوليت؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "الدوم أقل لفتًا بحكم شكله المدمج تحت السقف، ولأن الغطاء الكروي يُخفي اتجاه العدسة. البوليت مصمَّم ليكون ظاهرًا كأثر ردع، فهو الأنسب حين تريد أن يعلم المارّ أن المكان مراقَب."
      }
    },

    {
      "@type": "Question",
      "name": "ما الفرق في سهولة التركيب بين كاميرا الدوم والبوليت؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "البوليت أسرع تركيبًا على الجدران لأنه يأتي بذراع جاهز. الدوم يحتاج تجهيز السقف وتمرير الكابل من خلفه، مما يزيد وقت العمالة."
      }
    },
    {
      "@type": "Question",
      "name": "هل يؤثر نوع الكاميرا على تكلفة التركيب الإجمالية؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "نعم، عبر أجرة العمالة، وطول الكابلات، ودرجة الحماية، وعدد الكاميرات لتغطية زاوية معينة. اختيار النوع الأنسب لكل موضع يُخفض العدد وأجرة التمديد معًا."
      }
    },
    {
      "@type": "Question",
      "name": "كيف أعرف عدد الكاميرات الذي يحتاجه مكاني قبل طلب العرض؟",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "لا يمكنك أن تعرف بدقة قبل المعاينة، لكن يمكنك تقريبه بحصر نقاط الدخول والخروج والمساحات المفتوحة ونقاط القيمة العالية. الرقم النهائي يظهر بعد الزيارة الميدانية."
      }
    }
  ]
